    {
      "topic": {
        "text": "while loop vs do-while loop",
        "refs": ["Q0003", "Q0004", "Q0005"]
      },
      "explanation_text": {
        "text": "A while loop checks its condition before each iteration, so if the condition is false the loop body may never execute. A do-while loop checks its condition after the loop body, guaranteeing that the body executes at least once even if the condition is false.",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "String comparison in Java",
        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "To compare the value of two strings you must use the equals() method of the String class; using the == operator compares object references, not content.",
        "refs": ["Q0000"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Case‑insensitive input handling",
        "refs": ["Q0002"]
      },
      "explanation_text": {
        "text": "Calling toLowerCase() on the user input converts it to all lowercase, allowing the program to recognize commands like \"quit\" regardless of the case used by the user.",
        "refs": ["Q0002"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Scanner object usage",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "Creating a new Scanner object inside a loop for each iteration unnecessarily allocates memory and can lead to resource leaks; it is better to instantiate a single Scanner before the loop and reuse it.",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "While loops may never execute if their condition is false at the start.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Do‑while loops always execute their body at least once.",
        "refs": ["Q0004", "Q0005"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Instantiating a Scanner inside a loop creates a new object each iteration, which is unnecessary and bad practice.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Using equals() with a preceding not operator (!input.equals(\"quit\")) checks that the input is not the string \"quit\".",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Converting input to lowercase with toLowerCase() enables case‑insensitive command detection.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    }
  ],
