  "procedures": [
    {
      "procedure_name": {
        "text": "Read user input in a loop until \"quit\" is entered",
        "refs": ["Q0000", "Q0002"]
      },
      "steps": [
        {
          "text": "Create a single Scanner object outside the loop (e.g., Scanner scanner = new Scanner(System.in);).",
          "refs": ["Q0001"]
        },
        {
          "text": "Enter a while loop with condition !input.equals(\"quit\").",
          "refs": ["Q0000"]
        },
        {
          "text": "Inside the loop, read a line with scanner.nextLine(), store it in a variable, and immediately convert it to lowercase using toLowerCase().",
          "refs": ["Q0002"]
        },
        {
          "text": "Echo the input back to the user (e.g., System.out.println(input);).",
          "refs": ["Q0002"]
        },
        {
          "text": "Loop repeats until the user types \"quit\" (any case).",
          "refs": ["Q0000", "Q0002"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "A loop that continuously prompts the user, reads input, normalizes case, echoes the input, and terminates when the user enters \"quit\".",
        "refs": ["Q0000", "Q0002"]
      }
    },
    {
      "procedure_name": {
        "text": "Implement the same logic using a do‑while loop",
        "refs": ["Q0003", "Q0004"]
      },
      "steps": [
        {
          "text": "Create a Scanner object before the loop.",
          "refs": ["Q0001"]
        },
        {
          "text": "Start a do block, read input, convert to lowercase, and echo it.",
          "refs": ["Q0003"]
        },
        {
          "text": "Close the do block with while (!input.equals(\"quit\"));",
          "refs": ["Q0004"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "A do‑while loop that guarantees the body runs at least once before checking the quit condition.",
        "refs": ["Q0003", "Q0004"]
      }
    }
  ],
